--- src/track.js ---
const registry = require('../events/registry.json');
const { RESERVED } = require('./reserved');
const consent = require('./consent');

const queue = [];

function track(name, props = {}) {
  if (!consent.analyticsAllowed()) return false;
  if (!registry[name]) throw new Error('unregistered event: ' + name);
  const clean = {};
  for (const [k, v] of Object.entries(props)) if (!RESERVED.includes(k)) clean[k] = v;
  queue.push({ name, props: clean, ts: Date.now() });
  return true;
}

module.exports = { track, queue };

